// === auto-generated standalone bg shader ===
// source: shaders/hinotori/99_bg_nebula.frag  (func: bg_nebula)
// 各 uniform はスライダーから調整可。time/resolution は vj が自動供給。

// @param uRingZoom      10..200  = 58.0
// @param uHoldProb      0..1     = 0.18
// @param uFreeHoverGain 0..30    = 12.0
// @param uFreeDriftGain 0..1     = 0.10
// @param uFreeZoomAmp   0..1.5   = 0.50
// @param uFreeZoomRate  0..1     = 0.10
// @param uBPM           20..220  = 120
// @param uBgZoom        0.1..4   = 1.0

uniform float uRingZoom;
uniform float uHoldProb;
uniform float uFreeHoverGain;
uniform float uFreeDriftGain;
uniform float uFreeZoomAmp;
uniform float uFreeZoomRate;
uniform float uBPM;
uniform float uBgZoom;
uniform float uCosGrad;   // Post FX の Cos Grad 強度を bg 側に供給 (各シェーダ固有の彩色を ON)
uniform float uSlotIsA;   // 1=このシェーダは Slot A (ベース) / 0=Slot B 等。透過対応シェーダが背景色判定に使用
uniform float iAudio;     // 音域(Band)+アタック(Attack)で整形した音声リアクト値 0..1 (vj が供給)
uniform float iAudioSeed; // アタックを拾うたびに変わる乱数 0..1 (vj が供給。棘ごとの係数変化用)

// Sandbox-compat (vj が自動接続)
uniform float time;
uniform vec2  resolution;
uniform sampler2D uFFT;   // 音声スペクトル(512x2 LUMINANCE: row0=FFT) vj が接続
uniform sampler2D uBsodText;  // BSOD 実テキスト(1024x768 RGBA) vj が接続

// iPan / iZoom は HEADER で宣言済 (vj が cursor keys / < > から供給)

// hinotori uniform 名にエイリアス
#define bpm    uBPM
#define bgZoom (uBgZoom * iZoom)

// beat は vj 側の Motion Mode (drone/beat) で切替:
//   drone (App.beatMode='drone')→ -1.0 (= isFree=true、time 駆動)
//   beat  (App.beatMode='beat') → BPM.beatCount() (拍数、isFree=false)
uniform float beat;

// 一部 bg / helper が参照する未使用 uniform / 値を const で吸収
#define bgCamPx (iPan * resolution * 0.5)
const vec2  bgPhotoSize   = vec2(1024.0);
// bg 関数が出力する透明度 (既定 1.0=不透明)。透過対応シェーダだけが書き換える。
float bgAlpha = 1.0;
const float manualZoomOffset = 1.0;

// ---- helpers (constants/utils/beat/smooth_random/free_zoom/camera/palette/color_beat/free_motion/drone_seamless) ----
uniform vec3 uGradStops[8];
uniform float uGradPos[8];
uniform int uGradN;
// ---- shaders/hinotori/05_constants.frag ----
// =====================================================
// constants
// =====================================================
const float PI  = 3.14159265359;
const float TAU = 6.28318530718;

// TIMES は for ループ境界に使われるため const のまま (GLSL ES 1.00 制約)
const int   TIMES = 4;

// 旧 const は uniform 化 (00_header.frag を参照):
//   ZOOM -> uRingZoom, RING_SAT -> uRingSat, RING_BRI -> uRingBri,
//   HOLD_PROB -> uHoldProb,
//   FREE_HOVER_GAIN -> uFreeHoverGain, FREE_DRIFT_GAIN -> uFreeDriftGain,
//   FREE_ZOOM_AMP   -> uFreeZoomAmp,   FREE_ZOOM_RATE  -> uFreeZoomRate

// ---- shaders/hinotori/10_utils.frag ----
// =====================================================
// utils
// =====================================================
float hash21(vec2 p){
  return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453123);
}

float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float easeOutQuint(float x){
  return 1.0 - pow(1.0 - x, 5.0);
}

float sstep(float a,float b,float x){
  float t = clamp((x-a)/(b-a),0.0,1.0);
  return t*t*(3.0-2.0*t);
}

vec2 uvCover(vec2 uv, vec2 canvas, vec2 tex){
  float ca = canvas.x / canvas.y;
  float ta = tex.x / tex.y;
  vec2 s = (ca > ta) ? vec2(1.0, ca/ta) : vec2(ta/ca, 1.0);
  return (uv - 0.5) / s + 0.5;
}

float wrapDelta(float a,float b){
  float d = a - b;
  return d - floor(d + 0.5);
}

vec3 saturateColor(vec3 c,float s){
  float l = dot(c, vec3(0.299,0.587,0.114));
  return mix(vec3(l), c, s);
}

// 4x4 Bayer (0..1)
float bayer4(vec2 p){
  vec2 f = mod(p, 4.0);
  float x = f.x, y = f.y;
  float v = 0.0;

  if(y < 1.0){
    if(x < 1.0) v = 0.0;   else if(x < 2.0) v = 8.0;  else if(x < 3.0) v = 2.0;  else v = 10.0;
  }else if(y < 2.0){
    if(x < 1.0) v = 12.0;  else if(x < 2.0) v = 4.0;  else if(x < 3.0) v = 14.0; else v = 6.0;
  }else if(y < 3.0){
    if(x < 1.0) v = 3.0;   else if(x < 2.0) v = 11.0; else if(x < 3.0) v = 1.0;  else v = 9.0;
  }else{
    if(x < 1.0) v = 15.0;  else if(x < 2.0) v = 7.0;  else if(x < 3.0) v = 13.0; else v = 5.0;
  }
  return (v + 0.5) / 16.0;
}

// ---- shaders/hinotori/15_beat.frag ----
// =====================================================
// FREE / BEAT unified beat
// =====================================================
bool isFree(){
  bool f = false;
  if(beat < 0.0) f = true;
  return f;
}

float freeBeat(){
  float bpmScale = bpm / 120.0;
  return time * 6.0 * bpmScale;
}

float getBeat(){
  float bt = beat;
  if(isFree()){
    bt = freeBeat();
  }
  return bt;
}

// ---- shaders/hinotori/20_smooth_random.frag ----
// =====================================================
// smooth random helpers
// =====================================================
float smooth01(float x){
  return x*x*(3.0-2.0*x);
}

float vnoise1(float t, float salt){
  float i = floor(t);
  float f = fract(t);
  float e = smooth01(f);
  float a = hash21(vec2(i, salt));
  float b = hash21(vec2(i + 1.0, salt));
  return mix(a, b, e);
}

float fbm1(float t, float salt){
  float n = 0.0;
  float amp = 0.55;
  float frq = 0.22;
  for(int k=0;k<4;k++){
    n += (vnoise1(t*frq, salt + float(k)*19.7) - 0.5) * 2.0 * amp;
    amp *= 0.55;
    frq *= 2.05;
  }
  return n;
}

float freeSeed(float bt, float rate, float salt){
  float t = bt * rate;
  return vnoise1(t, salt);
}

// ---- shaders/hinotori/22_free_zoom.frag ----
// =====================================================
// FREE zoom
// =====================================================
float freeZoom(float bt, float salt){
  float z = vnoise1(bt * uFreeZoomRate, salt + 900.1);
  z = (z - 0.5) * 2.0;
  z = z * (0.85 + 0.15 * vnoise1(bt * (uFreeZoomRate * 2.0), salt + 901.7));
  return 1.0 + z * uFreeZoomAmp;
}

// ---- shaders/hinotori/25_camera.frag ----
// =====================================================
// DRAW mode random camera
// =====================================================
vec2 drawRandomCam(float bt, float salt){
  float blk = floor(bt);
  float rx = hash21(vec2(blk, salt + 100.0));
  float ry = hash21(vec2(blk, salt + 200.0));
  vec2 range = resolution * 0.0025;
  vec2 offset = vec2((rx - 0.5) * 3.0 * range.x, (ry - 0.5) * 3.0 * range.y);
  return bgCamPx + offset;
}

float drawRandomZoom(float bt, float salt){
  float blk = floor(bt);
  float rz = hash21(vec2(blk, salt + 300.0));
  return mix(1.5, 2.0, rz);
}

float drawRandomAngle(float bt, float salt){
  float blk = floor(bt);
  float ra = hash21(vec2(blk, salt + 400.0));
  float angleRange = 15.0 * PI / 180.0;
  return (ra - 0.5) * 2.0 * angleRange;
}

vec2 applyZoomToFC(vec2 fc, float zoom){
  vec2 c = 0.5 * resolution.xy;
  return (fc - c) / zoom + c;
}

// ---- shaders/hinotori/30_palette.frag ----
// =====================================================
// palette
// =====================================================
vec3 pal(int i){
  if(i==0)  return vec3(0.00,0.90,0.73);
  if(i==1)  return vec3(0.70,0.74,0.74);
  if(i==2)  return vec3(0.90,0.58,0.49);
  if(i==3)  return vec3(0.88,0.31,0.29);
  if(i==4)  return vec3(0.16,0.67,0.57);
  if(i==5)  return vec3(0.27,0.82,0.70);
  if(i==6)  return vec3(0.47,0.79,0.67);
  if(i==7)  return vec3(0.07,0.80,0.72);
  if(i==8)  return vec3(0.65,0.42,0.49);
  if(i==9)  return vec3(0.82,0.68,0.18);
  if(i==10) return vec3(0.44,0.60,0.83);
  return           vec3(0.11,0.59,0.88);
}

vec3 palPick(float x){
  return pal(int(floor(fract(x)*12.0)));
}

// =====================================================
// cosineGradient 共有パレット (全 cosGrad 対応シェーダ + 全体 cosGrad で共通)
//   uCosPalette でパレット選択。時間回転は全体 cosGrad と同期 (getBeat()*0.04)。
//   主要5色相: 浅葱 → 群青 → サーモンピンク → ライム → シルバー (シルバー比率を多めに)。
// =====================================================
uniform int uCosPalette;
vec3 cosGradColor(float t){
  float tt = clamp(t, 0.0, 1.0);
  if(uGradN < 2) return vec3(tt);
  vec3 mapped = uGradStops[0];
  for(int i=0;i<7;i++){ if(i < uGradN-1){ float p0=uGradPos[i],p1=uGradPos[i+1]; if(tt>=p0){ float f=clamp((tt-p0)/max(p1-p0,0.0001),0.0,1.0); mapped=mix(uGradStops[i],uGradStops[i+1],f); } } }
  return mapped;
}

// ---- shaders/hinotori/32_color_beat.frag ----
// =====================================================
// beat helpers
// =====================================================
float colorBeat(float bt){
  return floor(bt) + easeOutQuint(fract(bt));
}

// ---- shaders/hinotori/35_free_motion.frag ----
// =====================================================
// random move control (per-beat)
// =====================================================
struct MoveRand {
  float dir;
  float dist;
  float speed;
  float hold;
};

MoveRand moveRand(float bt, float salt){
  float blk = floor(bt);
  float r0 = hash21(vec2(blk, 0.3 + salt));
  float r1 = hash21(vec2(blk, 1.1 + salt));
  float r2 = hash21(vec2(blk, 2.7 + salt));
  float r3 = hash21(vec2(blk, 5.9 + salt));
  MoveRand m;
  m.hold  = step(1.0 - uHoldProb, r0);
  m.dir   = step(0.5, r1) * 2.0 - 1.0;
  m.dist  = mix(0.20, 1.20, r2);
  m.speed = mix(0.45, 2.40, r3);
  return m;
}

float freeBlock(float bt){
  float scale = bpm / 120.0;
  return floor(bt * 0.15 * scale);
}

float freeDriftWeight(float bt, float salt){
  float v = vnoise1(bt * 0.06, salt + 77.7);
  return smoothstep(0.90, 1.00, v);
}

vec2 freeDriftDir(float bt, float salt){
  float blk = freeBlock(bt);
  float a = hash21(vec2(blk, salt + 13.7)) * TAU;
  return vec2(cos(a), sin(a));
}

vec2 freeHoverVec(float bt, float salt){
  float t = bt * 0.25;
  float x = fbm1(t, salt + 1.0);
  float y = fbm1(t, salt + 9.1);
  return vec2(x, y);
}

float randomMoveTime(float bt, float baseScale, float salt){
  if(isFree()){
    float w = freeDriftWeight(bt, salt);
    vec2 dir = freeDriftDir(bt, salt);
    float spd = baseScale * uFreeDriftGain * (bpm / 120.0);
    float driftVal = (dir.x + dir.y) * bt * spd;
    vec2 hv = freeHoverVec(bt, salt);
    float slow = fbm1(bt * 0.05, salt + 100.0);
    float mid  = hv.x + hv.y;
    float hoverVal = (slow * 1.4 + mid * 0.6) * baseScale * uFreeHoverGain;
    return mix(hoverVal, driftVal, w);
  }
  MoveRand m = moveRand(bt, salt);
  float blk = floor(bt);
  float ph  = fract(bt);
  float e   = easeOutQuint(ph);
  float adv = mix(e * m.speed, 0.0, m.hold);
  return (blk + adv) * m.dir * m.dist * baseScale;
}

// ---- shaders/hinotori/37_drone_seamless.frag ----
// =====================================================
// DRONE mode seamless camera
// =====================================================
vec2 droneSeamlessCam(float bt, float salt){
  float drift = 0.12;
  float tx = randomMoveTime(bt, TAU * 0.08, salt + 100.0);
  float ty = randomMoveTime(bt, TAU * 0.06, salt + 200.0);
  vec2 offset = vec2(tx, ty) * resolution.y * 0.1 * drift;
  return bgCamPx + offset;
}

float droneSeamlessZoom(float bt, float salt){
  float drift = 0.12;
  float z = vnoise1(bt * uFreeZoomRate, salt + 500.0);
  z = (z - 0.5) * 2.0;
  z = z * (0.85 + 0.15 * vnoise1(bt * (uFreeZoomRate * 2.0), salt + 501.0));
  return 1.0 + z * (uFreeZoomAmp * 0.5) * drift;
}

float droneSeamlessAngle(float bt, float salt){
  float drift = 0.12;
  float a = vnoise1(bt * 0.08, salt + 600.0);
  a = (a - 0.5) * 2.0;
  float angleRange = 10.0 * PI / 180.0;
  return a * angleRange * drift;
}



// ---- beat-mode time jump (内部で getBeat 未使用のシェーダ用) ----

float _bgTime;
void _setBgTime(){
  if(beat >= 0.0){
    // 各拍ごとに大きなランダムオフセットを time に加算 → フレームが拍境界でジャンプ
    float blk = floor(beat);
    float ofs = fract(sin(blk*78.233 + 1.7)*4373.7) * 1000.0;
    _bgTime = time + ofs;
  } else {
    _bgTime = time;
  }
}

// ---- bg function: bg_nebula ----
// =====================================================
// bg_nebula  (H55)
//   Source : Shadertoy "Nebula WIP"  https://www.shadertoy.com/view/lf3XRj
//   simplex noise でゆらぐ 3 枚のブロブを重ねた星雲。テクスチャ不使用。
//   改変: iTime,iResolution → _bgTime,resolution / bgZoom・bgCamPx でズーム/パン。
//         cosineGradient(uCosGrad)対応 / Slot B はブロブの不透明度で透過。
//         ヘルパは neb_ で名前空間化(snoise 等の衝突回避)。
// =====================================================

vec3 neb_mod289(vec3 x){ return x - floor(x * (1.0/289.0)) * 289.0; }
vec4 neb_mod289(vec4 x){ return x - floor(x * (1.0/289.0)) * 289.0; }
vec4 neb_permute(vec4 x){ return neb_mod289(((x * 34.0) + 10.0) * x); }
vec4 neb_taylorInvSqrt(vec4 r){ return 1.79284291400159 - 0.85373472095314 * r; }

float neb_snoise(vec3 v){
  const vec2 C = vec2(1.0/6.0, 1.0/3.0);
  const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
  vec3 i  = floor(v + dot(v, C.yyy));
  vec3 x0 = v - i + dot(i, C.xxx);
  vec3 g = step(x0.yzx, x0.xyz);
  vec3 l = 1.0 - g;
  vec3 i1 = min(g.xyz, l.zxy);
  vec3 i2 = max(g.xyz, l.zxy);
  vec3 x1 = x0 - i1 + C.xxx;
  vec3 x2 = x0 - i2 + C.yyy;
  vec3 x3 = x0 - D.yyy;
  i = neb_mod289(i);
  vec4 p = neb_permute(neb_permute(neb_permute(
            i.z + vec4(0.0, i1.z, i2.z, 1.0))
          + i.y + vec4(0.0, i1.y, i2.y, 1.0))
          + i.x + vec4(0.0, i1.x, i2.x, 1.0));
  float n_ = 1.0/7.0;
  vec3 ns = n_ * D.wyz - D.xzx;
  vec4 j = p - 49.0 * floor(p * ns.z * ns.z);
  vec4 x_ = floor(j * ns.z);
  vec4 y_ = floor(j - 7.0 * x_);
  vec4 x = x_ * ns.x + ns.yyyy;
  vec4 y = y_ * ns.x + ns.yyyy;
  vec4 h = 1.0 - abs(x) - abs(y);
  vec4 b0 = vec4(x.xy, y.xy);
  vec4 b1 = vec4(x.zw, y.zw);
  vec4 s0 = floor(b0) * 2.0 + 1.0;
  vec4 s1 = floor(b1) * 2.0 + 1.0;
  vec4 sh = -step(h, vec4(0.0));
  vec4 a0 = b0.xzyw + s0.xzyw * sh.xxyy;
  vec4 a1 = b1.xzyw + s1.xzyw * sh.zzww;
  vec3 p0 = vec3(a0.xy, h.x);
  vec3 p1 = vec3(a0.zw, h.y);
  vec3 p2 = vec3(a1.xy, h.z);
  vec3 p3 = vec3(a1.zw, h.w);
  vec4 norm = neb_taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2,p2), dot(p3,p3)));
  p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
  vec4 m = max(0.5 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
  m *= m;
  return 105.0 * dot(m*m, vec4(dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3)));
}

vec4 neb_blend(vec4 fg, vec4 bg){ return fg * fg.a + bg * (1.0 - fg.a); }

float neb_shape(vec2 uv, float radius, float softness, float noiseIntensity, float noiseOffset){
  float noise = neb_snoise(vec3(uv * 1.2 + noiseOffset, noiseOffset + _bgTime * 0.3));
  uv += noise * noiseIntensity;
  float dist = length(uv);
  return smoothstep(radius, radius - softness, dist);
}

vec3 bg_nebula(vec2 fc){
  vec2 I  = (fc - resolution*0.5) / max(bgZoom, 0.001) + resolution*0.5 + bgCamPx;
  vec2 uv = I / resolution.xy;
  uv -= 0.5;
  uv.x *= resolution.x / resolution.y;
  uv.x *= 0.35;                                   // 横長の星雲

  const vec3 col0 = vec3(0.157, 0.235, 0.424);
  const vec3 col1 = vec3(0.588, 0.682, 0.906);
  const vec3 col2 = vec3(0.325, 0.514, 0.843);

  vec4 bg = vec4(0.0);
  vec4 l0 = vec4(col0, neb_shape(uv, 0.4, 0.3, 0.2, 4.0) * 1.3);
  vec4 l1 = vec4(col1, neb_shape(uv, 0.6, 0.4, 0.1, 6.0) * 1.2);
  vec4 l2 = vec4(col2, neb_shape(uv, 0.4, 0.8, 0.1, 10.0));
  vec4 layers = neb_blend(l0, bg);
  layers = neb_blend(l1, layers);
  layers = neb_blend(l2, layers);
  vec3 color = layers.rgb * layers.a;

  if(abs(uCosGrad) > 0.0001){
    float lum = dot(color, vec3(0.299, 0.587, 0.114));
    color = mix(color, cosGradColor(lum) * (0.2 + 1.4*lum), abs(uCosGrad));
  }
  bgAlpha = (uSlotIsA > 0.5) ? 1.0 : clamp(layers.a, 0.0, 1.0);  // Slot B はブロブ部分のみ
  return color;
}


// ---- entrypoint (Shadertoy-form; vj が main() にラップ) ----
void mainImage(out vec4 fragColor, in vec2 fragCoord){
  _setBgTime();
  vec3 col = bg_nebula(fragCoord);
  fragColor = vec4(col, bgAlpha);
}
